function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives:  (Prioritize accuracy over extreme verbosity here)
  for (let i = 0; i < words.length; i++) {
    if (/[a-zA-Z]+(?:[-][a-zA-Z]+)*ivamente?/.test(words[i]) && !/[0-9]/.test(words[i])) {  // Basic adjective detection regex
      adjectiveIndices.push(i); 
    }
  }

  // 2. Swap if Adjectives Exist:
  if (adjectiveIndices.length >= 2) {
    const [firstAdjIndex, secondAdjIndex] = adjectiveIndices.slice(0, 2);
    [words[firstAdjIndex], words[secondAdjIndex]] = [words[secondAdjIndex], words[firstAdjIndex]]; 
  }

  // 3. Reconstruct & Return:
  return words.join(' ');
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(`Original: ${originalSentence}`);
console.log(`Modified: ${modifiedSentence}`); 
```

