% 1. Image Loading and Preprocessing
input_image = imread('image.jpg');
gray_image = rgb2gray(input_image); 

% 2. Gaussian Smoothing (Noise Reduction)
%   - Choose a suitable sigma value (standard deviation) for your noise level.
%   - Experiment with values like 1.0 or 1.5 often works well.
sigma = 1.5; 
gaussian_filter = fspecial('gaussian', [5 5], sigma); % Create Gaussian kernel
smoothed_image = imfilter(gray_image, gaussian_filter, 'replicate'); % Apply filtering

% 3. Sobel Operator Application (Enhanced Edges)
sobel_x = [-1 0 1; -2 0 2; -1 0 1]; 
sobel_y = [-1 -2 -1; 0 0 0; 1 2 1]; 

edge_image_x = conv2(double(smoothed_image), sobel_x, 'same');
edge_image_y = conv2(double(smoothed_image), sobel_y, 'same');
edge_image = sqrt(edge_image_x.^2 + edge_image_y.^2); % Magnitude Calculation

% 4. Thresholding (Optional but Recommended)
%   -  Improve edge visibility by setting a threshold to binarize edges.
threshold = 0.15 * max(edge_image(:));  %  Adjust this threshold empirically
binary_edges = edge_image > threshold;

% 5. Visualization
imshow(binary_edges, []); % Display binary edge map (black/white)
title('Edges after Gaussian Filtering and Sobel');

```

