#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n, bool& validInput) {
    if (n <= 0) {  // Base case: Generate nothing for non-positive counts
        validInput = false;
        return 0;
    } else if (n == 1) {
        return a;  // First element is provided 'a'
    } else if (n == 2) {
        return b;  // Second element is provided 'b'
    } else {
        int nextFib = a + b;
        validInput = true;  // Input handled successfully so far
        return fibonacci(b, nextFib, n - 1, validInput); // Recursive call
    }
}

int main() {
    int num1, num2, count;
    bool inputValid = true;

    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> num1 >> num2)) {  // Input validation for numbers
        cout << "Invalid input. Please enter two integers: ";
        cin.clear();  // Clear error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }

    cout << "Enter the desired sequence length: ";
    while (!(cin >> count) || count <= 0) {  // Validate count as positive integer
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    // Error handling incorporated into recursive call
    int result = fibonacci(num1, num2, count, inputValid);

    if (inputValid) {
        cout << "Fibonacci Sequence (";
        for (int i = 1; i <= count; ++i) {
            if (i == count) {
                cout << result;  // Output the last generated Fibonacci number
            } else {
                result = fibonacci(num2, result, count - i, inputValid); // Recursive generation and output (comma-separated)
                cout << result << ", ";
            }
        }
        cout << ")\n";
    }

