```cpp
#include <iostream>
#include <vector>
#include <jsoncpp/json/json.h> // Assuming jsoncpp library for JSON handling

using namespace std;
using Json = Json::Value;

// In-place Bubble Sort with optimized memory usage
void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    do {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }
        n--; // Shrink the unsorted portion after each pass
    } while (swapped);
}

// Function to integrate with JSON handling (Job Application System Example)
Json processApplicantData(const Json& applicantJson) {
    Json outputJson;

    // 1. Extract integer scores (e.g., skill ratings) from JSON
    const Json& scoresJson = applicantJson["scores"]; // Assuming "scores" key holds an array
    vector<int> skillScores(scoresJson.getArray().size());
    for (size_t i = 0; i < scoresJson.getArray().size(); ++i) {
        skillScores[i] = scoresJson[i].asInt();
    }

    // 2. Apply bubbleSort for ascending order (minimal memory impact)
    bubbleSort(skillScores);

    // 3. Construct output JSON with sorted scores
    Json sortedScoresJson;
    for (int score : skillScores) {
        sortedScoresJson.append(score);
    }
    outputJson["sorted_skills"] = sortedScoresJson; 

    return outputJson;
}

int main() {
